import math


def poly(xs: list, x: float):
    """
    Evaluates polynomial with coefficients xs at point x.
    return xs[0] + xs[1] * x + xs[1] * x^2 + .... xs[n] * x^n
    """
    return sum([coeff * math.pow(x, i) for i, coeff in enumerate(xs)])


def find_zero(xs: list):
    """ xs are coefficients of a polynomial.
    find_zero find x such that poly(x) = 0.
    find_zero returns only only zero point, even if there are many.
    Moreover, find_zero only takes list xs having even number of coefficients
    and largest non zero coefficient as it guarantees
    a solution.
    >>> round(find_zero([1, 2]), 2) # f(x) = 1 + 2x
    -0.5
    >>> round(find_zero([-6, 11, -6, 1]), 2) # (x - 1) * (x - 2) * (x - 3) = -6 + 11x - 6x^2 + x^3
    1.0
    """
    if len(xs) % 2 != 0:
        raise ValueError("The list of coefficients must have an even number of elements.")

    # Newton's method for finding roots
    def newtons_method(f, df, x0, tol=1e-10, max_iter=1000):
        x = x0
        for _ in range(max_iter):
            f_x = f(x)
            if abs(f_x) < tol:
                return x
            df_x = df(x)
            if abs(df_x) < tol:
                raise ValueError("Derivative near zero; no convergence guaranteed.")
            x -= f_x / df_x
        raise ValueError("Maximum number of iterations reached; no convergence.")

    # Define the polynomial and its derivative
    def f(x):
        return poly(xs, x)

    def df(x):
        return sum([coeff * i * math.pow(x, i - 1) for i, coeff in enumerate(xs)])

    # Initial guess is the index of the largest coefficient, adjusted for sign
    initial_guess = abs(xs[0]) if xs[0] != 0 else abs(xs[1])

    return newtons_method(f, df, initial_guess)
