def check_dict_case(d):
    if not d:  # Return False if the dictionary is empty
        return False

    lower = None
    upper = None

    for key in d:
        if not isinstance(key, str):  # Ensure all keys are strings
            return False
        if lower is None and key.islower():
            lower = True
        elif lower and key.isupper():
            return False
        if upper is None and key.isupper():
            upper = True
        elif upper and key.islower():
            return False

