def valid_date(date):
    import re

    # Rule 1: The date string is not empty.
    if not date:
        return False

    # Rule 4: The date should be in the format mm-dd-yyyy
    date_pattern = re.compile(r'^(\d{1,2})-(\d{1,2})-(\d{4})$')
    match = date_pattern.match(date)
    if not match:
        return False

    month, day, year = map(int, match.groups())

    # Rule 2: The number of days is not less than 1 or higher than 31 days for months 1,3,5,7,8,10,12. And the number of days is not less than 1 or higher than 30 days for months 4,6,9,11. And, the number of days is not less than 1 or higher than 29 for the month 2.
    if month in [1, 3, 5, 7, 8, 10, 12]:
        if not (1 <= day <= 31):
            return False
    elif month in [4, 6, 9, 11]:
        if not (1 <= day <= 30):
            return False
    elif month == 2:
        if not (1 <= day <= 29):
            return False

    # Rule 3: The months should not be less than 1 or higher than 12.
    if not (1 <= month <= 12):
        return False

    return True
