def tri(n):
    def tribonacci_tail(n, a, b, c):
        if n == 1:
            return [a]
        elif n % 2 == 0:
            return tribonacci_tail(n - 1, b, c, 1 + b // 2)
        else:
            return tribonacci_tail(n - 1, b, c, a + b + c)

    if n == 0:
        return [3]
    else:
        t1, t2, t3 = 3, 2, 8
