def specialFilter(nums):
    def is_odd(n):
        return n % 2 != 0

    def has_odd_first_and_last(num):
        str_num = str(abs(num))
        first_digit = int(str_num[0])
        last_digit = int(str_num[-1])
        return is_odd(first_digit) and is_odd(last_digit)

    count = 0
    for num in nums:
        if num > 10 and has_odd_first_and_last(num):
            count += 1
    return count

# Example usage:
print(specialFilter([15, -73, 14, -15]))  # Output: 1
print(specialFilter([33, -2, -3, 45, 21, 109]))  # Output: 2
